import { getHostEndpoint } from './_endpoint';
/**
 * Creates a cryptographic OAuth state and challenge pair for use in the PKCE authorization flow.
 *
 * @param state - An optional opaque string to embed in the OAuth state parameter. Defaults to an empty string.
 * @returns A promise resolving to an object containing the `state` token and PKCE `challenge`.
 * @public
 */
export const createOAuthState = (state = '') => {
    return getHostEndpoint().call.createOAuthState(state);
};
